INSERT INTO `components_blocks_page_highlight_w_img` VALUES (1,'Meet Our Top-Rated Faculty','<p>&nbsp;</p><p>&nbsp;</p><p>&nbsp;</p><p>&nbsp;</p><p>&nbsp;</p><p><span style=\"background-color:transparent;color:#501549;font-family:Arial, \'Helvetica Neue\', Helvetica, \'Source Sans Pro\', sans-serif;font-size:21px;\">At CME Avenue, our mission is to excel in providing comprehensive and up-to-date continuing education solutions tailored for medical coding, billing, management, and auditing professionals. We are dedicated to delivering top tier learning experiences, ensuring ongoing professional development and compliance within the healthcare industry. Our commitment lies in offering meticulously curated curriculum and expert instructors, fostering a culture of continuous learning and advancement in our learners\' specific fields.</span></p>'),(2,'exceptional learning experiences, led by top-rated faculty','<p>&nbsp;</p><p>&nbsp;</p><p><span style=\"background-color:transparent;color:#501549;font-family:Arial,sans-serif;\">At CME Avenue, our mission is to excel in providing comprehensive and up-to-date continuing education solutions tailored for medical coding, billing, management, and auditing professionals. We are dedicated to delivering top tier learning experiences, ensuring ongoing professional development and compliance within the healthcare industry. Our commitment lies in offering meticulously curated curriculum and expert instructors, fostering a culture of continuous learning and advancement in our learners\' specific fields</span>.</p><p>&nbsp;</p><p>&nbsp;</p>'),(3,'OUR TINY EFFORT TO PROVIDE SUPPORT, SERVICES AND EDUCATION TO INDIVIDUALS, FAMILIES AND CAREGIVERS AFFECTED BY ALZHEIMER’S DISEASE AND RELATED DEMENTIAS NATIONWIDE, AND FUND RESEARCH FOR BETTER TREATMENT AND A CURE.','');
/*!40000 ALTER TABLE `components_blocks_page_highlight_w_img` ENABLE KEYS */;
UNLOCK TABLES;

