--
-- Table structure for table `courses`
--

DROP TABLE IF EXISTS `courses`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `courses` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `title` longtext,
  `short_desc` longtext,
  `price` decimal(10,2) DEFAULT NULL,
  `duration` decimal(10,2) DEFAULT NULL,
  `start_date` datetime(6) DEFAULT NULL,
  `end_date` datetime(6) DEFAULT NULL,
  `video_url` varchar(255) DEFAULT NULL,
  `venue_location` varchar(255) DEFAULT NULL,
  `keywords` varchar(255) DEFAULT NULL,
  `is_featured` tinyint(1) DEFAULT NULL,
  `order` bigint DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT NULL,
  `duration_unit` varchar(255) DEFAULT NULL,
  `timezone` varchar(255) DEFAULT NULL,
  `for_tax_law` tinyint(1) DEFAULT NULL,
  `slug` longtext,
  `uuid` varchar(255) DEFAULT NULL,
  `credit` varchar(255) DEFAULT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `published_at` datetime(6) DEFAULT NULL,
  `created_by_id` int unsigned DEFAULT NULL,
  `updated_by_id` int unsigned DEFAULT NULL,
  `webinar_id` varchar(255) DEFAULT NULL,
  `medium` varchar(255) DEFAULT NULL,
  `field_of_study` varchar(255) DEFAULT NULL,
  `program_number` varchar(255) DEFAULT NULL,
  `discount` varchar(255) DEFAULT NULL,
  `redirection_link` varchar(255) DEFAULT NULL,
  `survey_link` varchar(255) DEFAULT NULL,
  `credits_info` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `courses_uuid_unique` (`uuid`),
  KEY `courses_created_by_id_fk` (`created_by_id`),
  KEY `courses_updated_by_id_fk` (`updated_by_id`),
  CONSTRAINT `courses_created_by_id_fk` FOREIGN KEY (`created_by_id`) REFERENCES `admin_users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `courses_updated_by_id_fk` FOREIGN KEY (`updated_by_id`) REFERENCES `admin_users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=331 DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

