INSERT INTO `packages` VALUES (1,'2021 Federal Individual and Business Tax Update & Ethics for CPAs – A Three Part Series','2021 Federal Individual and Business Tax Update & Ethics for CPAs – A Three Part Series',279.00,'<p style=\"text-align:center;\"><span style=\"font-family:\'JetBrains Mono\', monospace;\"><strong>This package includes access to two</strong></span></p><p>&nbsp;</p><p>&nbsp;4-hour (Tax) and one 2-hour (Ethics) Live Webinars, access to a PDF (and other relevant materials), and a recording of the presentation (without CPE) to refer to at a later time. This cou<strong>rse will provide a co</strong>mprehensive review of the complexities of Form 1040 for the 2021 tax year. Included will be a thorough review of all tax codes created by the SECURE Act and the CARES Act. We will update and include any additional changes made to the internal revenue code prior to this lecture. These events can be taken independently of each other, or they can be taken as a series.</p>','2021-federal-individual-and-business-tax-update-and-ethics-for-cp-as-a-three-part-series',NULL,'2022-08-27 11:42:15.931000','2025-05-21 17:21:17.055000','2025-05-15 16:26:40.134000',NULL,2),(2,'package 33','subtitle',500.00,'<p>Outline</p>','package-33',489.00,'2022-09-29 11:35:39.167000','2024-03-21 11:39:29.750000',NULL,1,2),(3,'Package testing course','test',NULL,'','package-testing-course',NULL,'2022-10-07 07:01:08.701000','2025-05-15 16:35:57.609000','2025-05-15 16:35:57.605000',1,2),(4,'Test Package task ','Test Package task ',NULL,'<p>Test Package task Test Package task Test Package task Test Package task Test Package task Test Package task Test Package task Test Package task Test Package task Test Package task&nbsp;</p>','test-package-task',NULL,'2022-10-10 06:36:22.664000','2025-05-15 16:36:04.132000','2025-05-15 16:36:04.127000',1,2),(5,'Package Team ','Package Team ',200.00,'','package-team',NULL,'2022-11-29 11:30:13.459000','2025-05-15 16:35:41.058000','2025-05-15 16:35:41.052000',1,2),(8,'This is to test live course and this live course will tell you the reasons of day today life happiness, people can remain happy and can worrk happily if they start doing medidation daily. Click to see more and enroll now',NULL,NULL,'','this-is-to-test-live-course-and-this-live-course-will-tell-you-the-reasons-of-day-today-life-happiness-people-can-remain-happy-and-can-worrk-happily-if-they-start-doing-medidation-daily-click-to-see-more-and-enroll-now',298.00,'2023-02-03 07:04:23.703000','2025-05-15 16:36:11.027000','2025-05-15 16:36:11.018000',1,2),(9,'Free package',NULL,1.00,'','free-package',NULL,'2023-02-13 07:50:55.168000','2025-05-15 16:35:29.125000','2025-05-15 16:35:29.121000',1,2),(10,'Mix deal',NULL,0.00,'','mix-deal',NULL,'2023-02-13 07:53:16.868000','2024-03-21 11:42:00.033000',NULL,1,2),(11,'Package test course in month of september -1 & 2 Part','Package test course in month of september - Both 1 & 2 Part',278.00,'<p>Package test course in month of september -1 &amp; 2 Part</p>','package-test-course-in-month-of-september-1-and-2-part',229.00,'2023-07-17 06:02:12.700000','2025-05-15 16:35:48.521000','2025-05-15 16:35:48.516000',1,2);
